import {macAppShell,macSettingsView,bindMacSettings,cleanupMacSettings,bindMacWorkspace,macIcon} from './settings-design.js';
import {quoteMatchesStatus} from './quote-filters.js';
import {integrationsPanel,bindIntegrations,bindQuoteXero} from './integrations.js';
import {configureTurnstile,submissionAction,verificationToken} from './turnstile.js';
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={dashboard:'▦',quotes:'▤',contacts:'♧',templates:'▧',items:'◇',settings:'⚙',leads:'♧',reviews:'☆'};
let initialQuoteId=new URLSearchParams(location.search).get('quote');
const tenantPath=location.pathname.match(/^\/(\d+)(?:\/([^/]+))?/);
let db,view=tenantPath?.[2]||'dashboard',filter='All quotes',colleague='all',query='',sort='newest',editing=null,shared=null,dashboardMode='Active',activeCompanyId=tenantPath?'':localStorage.getItem('dowi-company-id')||'';
const baseCurrency=()=>db?.settings.currency||shared?.settings.currency||'USD';
const money=(n,currency=baseCurrency())=>new Intl.NumberFormat('en-US',{style:'currency',currency:/^[A-Z]{3}$/.test(currency||'')?currency:'USD',maximumFractionDigits:2}).format(n);
const quoteMoney=(n,q)=>money(n,q.currency||baseCurrency());
const statsMoney=(n,currency)=>db.currentUser?.permissions?.statsValues===false?'—':money(n,currency);
const reportingTotal=q=>total(q)*Number(q.exchangeRate||1);
const roundCurrency=n=>Math.round((n+Number.EPSILON)*100)/100;
const itemAmounts=i=>{const price=Number(i.price||0),value=Number(i.discountValue||0),unitDiscount=roundCurrency(i.discountType==='percent'?price*value/100:i.discountType==='amount'?Math.min(price,value):0),unitPrice=roundCurrency(Math.max(0,price-unitDiscount)),periods=i.repeatUnit?Math.max(1,Number(i.repeatCount||1)):1,qty=Number(i.qty||0);return {discount:roundCurrency(unitDiscount*qty*periods),revenue:roundCurrency(unitPrice*qty*periods),cost:roundCurrency(Number(i.cost||0)*qty*periods),unitPrice,periods}};
const included=i=>i.choiceGroup?i.selected!==false:!i.optional||i.selected!==false;
function quoteAmounts(q){const items=q.items.filter(included).map(itemAmounts),subtotal=roundCurrency(items.reduce((s,i)=>s+i.revenue,0)),discount=roundCurrency(items.reduce((s,i)=>s+i.discount,0)),cost=roundCurrency(items.reduce((s,i)=>s+i.cost,0)),tax=roundCurrency(subtotal*Number(q.tax||0)/100),revenueInCompanyCurrency=roundCurrency(subtotal*Number(q.exchangeRate||1)),profit=roundCurrency(revenueInCompanyCurrency-cost);return {subtotal,discount,cost,profit,revenueInCompanyCurrency,marginPercent:revenueInCompanyCurrency?profit/revenueInCompanyCurrency*100:0,tax,total:roundCurrency(subtotal+tax)}}
const total=q=>quoteAmounts(q).total;
const localDateInput=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fullDate=d=>new Date(d).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
const date=d=>new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const initials=s=>s.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();
const contact=q=>db.contacts.find(c=>c.id===q.contactId)||{name:'Deleted contact',company:'',color:'#eee'};
const badge=s=>`<span class="badge ${s.toLowerCase()}"><i></i>${s}</span>`;
async function api(url,method='GET',body){const action=submissionAction(url,method);if(action){const token=await verificationToken(action);if(token)body={...body,'cf-turnstile-response':token}}const headers={'Content-Type':'application/json'};if(tenantPath)headers['X-Dowi-Tenant-ID']=tenantPath[1];if(activeCompanyId)headers['X-Dowi-Company-ID']=activeCompanyId;const r=await fetch('/api/'+url,{method,headers,body:body?JSON.stringify(body):undefined});const j=await r.json();if(r.status===401&&!location.pathname.startsWith('/q/')){location.assign('/login');throw Error('Sign in required')}if(!r.ok)throw Object.assign(Error(j.error||'Something went wrong'),{status:r.status});if(j.turnstile)configureTurnstile(j.turnstile);return j}
async function uploadFile(file){if(!file||file.size>5*1024*1024)throw Error('Choose a file of at most 5 MB');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read this file'));reader.readAsDataURL(file)});return api('assets','POST',{name:file.name,base64})}
function attachmentLinks(q,customer){return (q.attachments||[]).map(a=>{const url=customer&&!new URLSearchParams(location.search).has('preview')?`/api/shared/${encodeURIComponent(location.pathname.split('/')[2])}/attachments/${a.id}`:`/${db.tenantId}/api/assets/${a.id}`;return `<div class="attachment-card">${a.type.startsWith('image/')?`<a href="${url}" download><img src="${url}?inline=1" alt="${esc(a.name)}"></a>`:''}<a href="${url}" download>↓ ${esc(a.name)}</a><small>${Math.ceil(a.size/1024)} KB</small></div>`}).join('')}
const toast=t=>{const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200)};
function bindCompanyControls(){
 const selector=$('#company-switcher');if(selector)selector.onchange=()=>{const company=db.companies.find(c=>c.id===selector.value);location.assign('/'+company.tenantCode+'/dashboard')};
 const add=document.querySelector('[data-action="new-company"]');if(add)add.onclick=()=>{modal(`<h2>Add a company</h2><p class="subtle">Each company has its own customers, quotes, settings and currency.</p><form id="company-form"><label>Company name<input name="company" required maxlength="200"></label><label>Base currency<select name="currency">${['HKD','USD','CNY','JPY','SGD','GBP','EUR','AUD','CAD','NZD','CHF'].map(c=>`<option ${c===baseCurrency()?'selected':''}>${c}</option>`).join('')}</select></label><button class="button primary">Create company workspace</button></form>`);$('#company-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const fields=Object.fromEntries(new FormData(e.target));const result=await api('companies','POST',{...fields,email:'',tax:0,terms:'',phone:'',address:'',website:''});activeCompanyId=result.company.id;localStorage.setItem('dowi-company-id',activeCompanyId);$('#modal').close();location.assign('/'+result.company.tenantCode+'/dashboard')}catch(error){toast(error.message);button.disabled=false}}};
}
async function refresh(){try{db=await api('workspace')}catch(error){if(tenantPath||error.status!==403||!activeCompanyId)throw error;activeCompanyId='';localStorage.removeItem('dowi-company-id');db=await api('workspace')}activeCompanyId=db.activeCompanyId||activeCompanyId;if(activeCompanyId)localStorage.setItem('dowi-company-id',activeCompanyId);render();if(initialQuoteId){const qid=initialQuoteId;initialQuoteId=null;if(db.quotes.some(q=>q.id===qid))openQuote(qid)}}
function shell(){if(db.tenantId)history.replaceState(null,'','/'+db.tenantId+'/'+view);return macAppShell(db,activeCompanyId,view)}
function heading(eyebrow,title,sub,button='New quote',action='new-quote'){
 const lang=localStorage.getItem('dowi-language')||'en';
 const titles={en:{dashboard:'Overview',quotes:'Quotations',contacts:'Customers',templates:'Templates',items:'Item library',leads:'Enquiries',reviews:'Reviews'},'zh-Hant':{dashboard:'總覽',quotes:'報價單',contacts:'客戶',templates:'範本',items:'常用項目',leads:'客戶查詢',reviews:'客戶評價'},'zh-Hans':{dashboard:'总览',quotes:'报价单',contacts:'客户',templates:'模板',items:'常用项目',leads:'客户咨询',reviews:'客户评价'}};
 return `<section class="page-heading"><div class="mac-heading-title"><span class="mac-page-glyph">${macIcon(view)}</span><div><h1>${titles[lang]?.[view]||title}</h1><p>${sub}</p></div></div>${button?`<button class="button primary" data-action="${action}">${macIcon('plus')}<span>${button}</span></button>`:''}</section>`
}
function dashboard(){const accepted=db.quotes.filter(q=>q.status==='Accepted');const open=db.quotes.filter(q=>['Sent','Viewed'].includes(q.status));const resolved=db.quotes.filter(q=>['Accepted','Declined'].includes(q.status));const rate=resolved.length?Math.round(accepted.length/resolved.length*100):0;const unresolved=db.quotes.filter(q=>q.messages.length&&!q.messages.at(-1).staff);const waiting=open.filter(q=>!(q.followups||[]).length||(q.followups||[]).some(f=>!f.done));const groups=dashboardMode==='Waiting'?[['Awaiting a response',waiting]]:[['Draft',db.quotes.filter(q=>q.status==='Draft')],['Sent',open],['Accepted',accepted.filter(q=>!q.archived)],['Declined',db.quotes.filter(q=>q.status==='Declined')]];const monthCounts=Array.from({length:12},(_,n)=>{const date=new Date();date.setDate(1);date.setMonth(date.getMonth()-11+n);return db.quotes.filter(q=>new Date(q.created).getFullYear()===date.getFullYear()&&new Date(q.created).getMonth()===date.getMonth()).length});const max=Math.max(1,...monthCounts);const points=monthCounts.map((v,n)=>`${20+n*34},${160-v/max*125}`).join(' ');return heading('','Overview','A clear view of your quotations and what comes next.','')+`<div class="reference-dashboard"><section class="reference-quotes"><div class="dashboard-tabs"><button data-dashboard-mode="Active" class="${dashboardMode==='Active'?'selected':''}">Active</button><button data-dashboard-mode="Waiting" class="${dashboardMode==='Waiting'?'selected':''}">Waiting <span>${waiting.length}</span></button></div><div class="questions-summary"><button class="text-button" data-action="unanswered">${unresolved.length} Unanswered Questions</button></div>${groups.map(([label,list])=>`<section class="quote-group"><header><h2>${label}</h2><button class="text-button" data-group="${label}">View all…</button><span>${list.length}</span></header>${list.slice(0,5).map(q=>`<button class="reference-quote-row" data-open="${q.id}"><div><strong>${esc(q.title)}</strong><small>${q.views?`<em>Viewed ${date(q.lastViewed||q.updated)}</em> `:['Sent','Viewed'].includes(q.status)?'<em class="unopened">Unopened</em> ':''}${esc(contact(q).company||contact(q).name)} #${q.number}</small></div><div><strong>${quoteMoney(total(q),q)}</strong><small>${date(q.updated)}</small></div></button>`).join('')}${!list.length?'<p class="group-empty">No quotes here yet.</p>':''}</section>`).join('')}</section><aside class="reference-analytics"><h2>Your sales at a glance</h2><p class="subtle">Pipeline totals converted using each quote’s saved rate · ${db.settings.currency}</p><div class="reference-stat-overview"><div><strong>${accepted.length}</strong><p>Quotes Accepted</p><span>${open.length}</span><small>Awaiting Acceptance</small></div><div class="donut" title="Acceptance rate among accepted and declined quotes" style="--rate:${rate*3.6}deg"><span>${rate}%</span></div></div><div class="pipeline-total"><label>Accepted value<strong>${statsMoney(accepted.reduce((s,q)=>s+reportingTotal(q),0),db.settings.currency)}</strong></label><label>Open pipeline<strong>${statsMoney(open.reduce((s,q)=>s+reportingTotal(q),0),db.settings.currency)}</strong></label></div><div class="chart-heading">Quotes created · last 12 months</div><svg class="quote-trend" viewBox="0 0 415 190" role="img" aria-label="Monthly quote creation counts: ${monthCounts.join(', ')}"><line x1="20" y1="35" x2="400" y2="35" stroke="#e8edf3"/><line x1="20" y1="98" x2="400" y2="98" stroke="#e8edf3"/><line x1="20" y1="160" x2="400" y2="160" stroke="#e8edf3"/><polygon points="20,160 ${points} 394,160" fill="#dae8f6"/><polyline points="${points}" fill="none" stroke="#2777c3" stroke-width="2"/>${[0,3,6,9,11].map(n=>{const date=new Date();date.setDate(1);date.setMonth(date.getMonth()-11+n);return `<text x="${20+n*34}" y="185" text-anchor="middle" fill="#8999ad" font-size="9">${date.toLocaleDateString('en-US',{month:'short'})}</text>`}).join('')}</svg><section class="panel activity"><div class="panel-heading"><h2>Latest activity</h2><button class="text-button" data-action="activity">View all…</button></div>${activityList(3)}</section><section class="followup"><h2>Follow-ups</h2><p>${waiting.length} open quotes are waiting for your next step. Schedule reminders from the quote’s staff view.</p><button class="button secondary" data-action="followups">Review open quotes →</button></section></aside></div>`}
function activityList(limit){const activities=db.quotes.flatMap(q=>q.activity.map(a=>({...a,q}))).sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)).slice(0,limit);return `<div class="activity-list">${activities.length?activities.map((a,n)=>`<button class="activity-row" data-open="${a.q.id}"><span class="activity-symbol ${n===0?'green':''}">${a.text.includes('accept')?'✓':a.text.includes('opened')?'◎':'↗'}</span><span><strong>${esc(contact(a.q).company||contact(a.q).name)}</strong><span>${esc(a.text)}</span><small>${date(a.date)} · Quote #${a.q.number}</small></span></button>`).join(''):'<p class="empty">Your activity will appear here.</p>'}</div>`}
function quoteTable(quotes){return `<div class="table-wrap"><table><thead><tr><th>QUOTE / CUSTOMER</th><th>STATUS</th><th>VALUE</th><th>UPDATED</th><th></th></tr></thead><tbody>${quotes.map(q=>{const c=contact(q);return `<tr data-open="${q.id}" tabindex="0" role="button" aria-label="Open ${esc(q.title)}"><td><div class="quote-cell"><span class="quote-icon">${macIcon('quotes')}</span><div><strong>${esc(q.title)}</strong><small>#${q.number} <span>·</span> ${esc(c.company||c.name)}</small>${q.assigneeName?`<small>Responsible: ${esc(q.assigneeName)}</small>`:''}</div></div></td><td>${badge(q.status)}</td><td class="amount">${quoteMoney(total(q),q)}</td><td class="table-date">${date(q.updated)}</td><td class="row-arrow">↗</td></tr>`}).join('')}</tbody></table>${!quotes.length?'<div class="empty">No quotes found. Create a quote or try another search.</div>':''}</div>`}
function quotesView(){let list=db.quotes.filter(q=>{const owner=q.assigneeId||'',ownerMatches=colleague==='all'||colleague==='unassigned'&&!owner||colleague==='past'&&!!owner&&!(db.teamMembers||[]).some(m=>m.id===owner&&m.active)||colleague===owner;const text=`${q.title} ${q.number} ${contact(q).name} ${contact(q).company} ${contact(q).email||''} ${q.assigneeName||''}`.toLocaleLowerCase();return quoteMatchesStatus(q,filter)&&ownerMatches&&query.trim().toLocaleLowerCase().split(/\s+/).every(term=>text.includes(term))});list.sort((a,b)=>sort==='value'?reportingTotal(b)-reportingTotal(a):Date.parse(b.updated)-Date.parse(a.updated));return heading('GREAT WORK STARTS HERE.','Your quotes','From the first hello to the final yes. Everything in one place.')+`<section class="panel"><div class="tabs">${['All quotes','Open','Draft','Accepted','Declined','Withdrawn'].map(f=>`<button data-filter="${f}" class="${filter===f?'selected':''}">${f} ${f==='All quotes'?`<span>${db.quotes.length}</span>`:''}</button>`).join('')}</div><div class="toolbar quote-list-toolbar"><label class="search"><span>⌕</span><input id="search" placeholder="Search quotes or customers…" value="${esc(query)}" aria-label="Search quotes"></label><label>Status<select id="quote-status-filter">${[['',['All quotes']],['Awaiting Acceptance',['Open','To follow up','Unanswered Questions','Unopened','Live, past 24 hours']],['By Status',['Draft','Editing','Sent','Viewed','Accepted','Completed']],['Not Going Ahead',['Expired','Declined','Withdrawn']]].map(([group,options])=>`${group?`<optgroup label="${group}">`:''}${options.map(value=>`<option value="${value}" ${filter===value?'selected':''}>${value==='Open'?'Awaiting Acceptance':value}</option>`).join('')}${group?'</optgroup>':''}`).join('')}</select></label><label>Responsible colleague<select id="quote-colleague-filter"><option value="all" ${colleague==='all'?'selected':''}>All Team Members</option><optgroup label="Team Members">${(db.teamMembers||[]).filter(m=>m.active).map(m=>`<option value="${esc(m.id)}" ${colleague===m.id?'selected':''}>${esc(m.email)}</option>`).join('')}</optgroup><optgroup label="Other"><option value="unassigned" ${colleague==='unassigned'?'selected':''}>Unassigned</option><option value="past" ${colleague==='past'?'selected':''}>Past Team Members</option></optgroup></select></label><select id="sort" aria-label="Sort quotes"><option value="newest" ${sort==='newest'?'selected':''}>Recently updated</option><option value="value" ${sort==='value'?'selected':''}>Highest value</option></select><button class="button secondary compact" data-action="export-quotes">↓ Export CSV</button></div>${quoteTable(list)}<div class="table-footer">${list.length} quotes <span>Each quote uses its own currency</span></div></section>`}
function collectionView(type){const map={contacts:['THE PEOPLE BEHIND THE PROJECTS.','Good connections.','Keep your customers close and their details closer.','New contact','new-contact'],items:['YOUR BEST WORK, ON REPEAT.','Your item library','Consistent pricing. Less typing. More time for the work.','New item','new-item'],templates:['A HEAD START ON SOMETHING GREAT.','Ready when you are.','Thoughtful starting points for your next great proposal.','New template','new-template']};const entries=db[type];return heading(...map[type])+`<div class="card-grid">${entries.map(r=>type==='contacts'?`<article class="panel contact-card"><span class="contact-avatar" style="background:${/^#[a-f0-9]{6}$/i.test(r.color)?r.color:'#e8ece9'}">${esc(initials(r.name))}</span><h2>${esc(r.name)}</h2><p>${esc(r.company)}</p><a href="mailto:${esc(r.email)}">${esc(r.email)}</a><div class="card-bottom"><span>${db.quotes.filter(q=>q.contactId===r.id).length} quotes</span><button class="text-button" data-customer="${r.id}">Create quote ↗</button><button class="text-button" data-edit-contact="${r.id}">Edit</button></div></article>`:`<article class="panel library-card"><div class="template-visual ${type==='items'?'item-visual':''}"><div class="mini-document"><span>${type==='items'?macIcon('items'):'<img src="/brand/dowi-quotes-mark.svg" alt="" width="22" height="22">'}</span><i></i><i></i><i></i></div><span class="template-spark">✦</span></div><div class="library-content"><h2>${esc(r.name)}</h2><p>${esc(r.description)}</p><div class="card-bottom"><span>${type==='items'?money(r.price):`${r.items.length} items`}</span><button class="text-button" ${type==='templates'?`data-template="${r.id}"`:`data-library="${r.id}"`}>Use ${type==='items'?'item':'template'} ↗</button>${type==='items'?`<button class="text-button" data-edit-item="${r.id}">Edit</button>`:''}</div></div></article>`).join('')}${!entries.length?'<div class="empty">Your collection is empty. Add your first entry above.</div>':''}</div>`}
function domainPanel(){const d=db.customDomain,managed=d&&!d.cloudflareId;return `<section class="panel settings-form domain-settings"><div class="section-label"><h2>Customer quote domain</h2>${d?`<span class="badge ${d.status==='active'?'accepted':d.status==='failed'?'declined':'sent'}">${esc(d.status)}</span>`:''}</div><p class="subtle">Use your own hostname for customer quotation pages. Each company has its own domain.</p>${d?`<p><strong>${esc(d.hostname)}</strong></p><p class="subtle">CNAME: <code>${esc(d.hostname)}</code> → <code>${esc(d.cnameTarget||db.customDomainTarget)}</code></p>${managed?'<p class="subtle">Managed by your platform administrator. Share the full quotation link with customers. Contact your administrator to change or remove this domain.</p>':`${d.txtName&&d.txtValue?`<p class="subtle">Cloudflare ownership check: create TXT record <code>${esc(d.txtName)}</code> with value <code>${esc(d.txtValue)}</code>.</p>`:''}<div class="form-footer"><button class="button secondary" type="button" id="refresh-domain">Check DNS and TLS</button><button class="text-button" type="button" id="remove-domain">Remove custom domain</button></div>`}`:!db.customDomainConfigured?'<p class="subtle">Contact your platform administrator to connect your customer quotation domain.</p>':`<form id="domain-form"><label>Customer portal hostname<input name="hostname" required maxlength="253" placeholder="quotes.yourcompany.com"></label><p class="subtle">CNAME target: <code>${esc(db.customDomainTarget)}</code>. HTTPS becomes available after DNS ownership and certificate validation.</p><button class="button primary">Connect domain</button></form>`}</section>`}
function aiProposalPanel(){return `<section class="panel settings-form"><div class="section-label"><h2>ChatGPT AI edit proposals</h2><button class="button secondary compact" type="button" id="load-ai-proposals">Review proposals</button></div><p class="subtle">Connect Dowi Quotes to ChatGPT using the MCP URL <code>${esc(db.mcpURL||location.origin+'/mcp')}</code>. ChatGPT can read quotes and suggest draft edits; changes only take effect after a company member approves them here.</p><div id="ai-proposal-count" class="subtle">No proposal list loaded.</div></section>`}
function proposalSummary(proposal){const q=proposal.quote||{},c=proposal.changes||{},next={...q,...c},before=quoteAmounts(q),after=quoteAmounts(next),currency=next.currency||db.settings.currency;return `<article class="ai-proposal"><div class="section-label"><div><strong>${esc(q.title||'Draft quotation')}</strong><small> · #${q.number||''} · proposed ${date(proposal.created)}</small></div><span class="badge draft">Pending</span></div><div class="proposal-change-grid"><span>Title</span><strong>${esc(c.title||q.title||'')}</strong><span>Items</span><strong>${(c.items||q.items||[]).length} · ${money(before.total,q.currency||db.settings.currency)} → ${money(after.total,currency)}</strong><span>Gross profit</span><strong>${money(before.profit,db.settings.currency)} → ${money(after.profit,db.settings.currency)} ${esc(db.settings.currency)}</strong>${c.tax!==undefined?`<span>Tax</span><strong>${Number(c.tax)}%</strong>`:''}${c.expires?`<span>Valid until</span><strong>${esc(fullDate(c.expires))}</strong>`:''}</div>${(c.items||q.items||[]).length?`<ul class="proposal-items">${(c.items||q.items||[]).map(i=>{const a=itemAmounts(i);return `<li>${esc(i.name||'Untitled item')} · Qty ${Number(i.qty||0)} · Price ${money(a.unitPrice,currency)} · Cost ${money(a.cost,db.settings.currency)} · Discount ${money(a.discount,currency)}</li>`}).join('')}</ul>`:''}<div class="form-footer"><button class="button secondary" data-reject-proposal="${proposal.id}">Reject</button><button class="button primary" data-approve-proposal="${proposal.id}">Approve changes</button></div></article>`}
async function aiProposalsDialog(){const result=await api('mcp-proposals');const proposals=result.proposals||[];$('#ai-proposal-count').textContent=proposals.length?`${proposals.length} pending ${proposals.length===1?'proposal':'proposals'} for this company.`:'No pending AI edit proposals.';modal(`<div class="eyebrow">YOUR REVIEW, YOUR CALL.</div><h2>AI edit proposals</h2><p class="subtle">Approving updates the draft. The quote is not sent to the customer.</p>${proposals.length?proposals.map(proposalSummary).join(''):'<p class="subtle">Nothing is waiting for review.</p>'}`,'wide');document.querySelectorAll('[data-approve-proposal]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`mcp-proposals/${button.dataset.approveProposal}/approve`,'POST',{});await refresh();$('#modal').close();toast('AI changes approved and saved to the draft')}catch(error){toast(error.message);button.disabled=false}});document.querySelectorAll('[data-reject-proposal]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`mcp-proposals/${button.dataset.rejectProposal}/reject`,'POST',{});await aiProposalsDialog();toast('Proposal rejected')}catch(error){toast(error.message);button.disabled=false}})}
function settingsView(){return macSettingsView(db)}

function leadsView(){const leads=db.leads||[];const base=db.publicPortalURL||location.origin;return heading('FROM A FIRST HELLO TO A GREAT PROJECT.','Leads','Enquiries from your public form, ready to turn into proposals.','Copy enquiry link','copy-lead-link')+`<section class="panel"><div class="panel-heading"><h2>Project enquiries <span class="count">${leads.length}</span></h2><a class="text-button" href="${esc(base)}/lead" target="_blank" rel="noopener">Open enquiry form ↗</a></div>${leads.map(l=>`<article class="lead-row"><div><h3>${esc(l.summary)}</h3><p>${esc(l.name)} · ${esc(l.company)} · <a href="mailto:${esc(l.email)}">${esc(l.email)}</a></p><p class="preserve-lines">${esc(l.details)}</p><small>${date(l.created)} · ${esc(l.status)}</small></div><div>${l.quoteId?`<button class="button secondary compact" data-open="${l.quoteId}">Open quote ↗</button>`:`<button class="button primary compact" data-convert-lead="${l.id}">Convert to draft →</button><select data-lead-status="${l.id}" aria-label="Enquiry status">${['New','Contacted','Archived'].map(status=>`<option ${l.status===status?'selected':''}>${status}</option>`).join('')}</select>`}</div></article>`).join('')||'<div class="empty">Share your enquiry form to start receiving leads.</div>'}</section>`}
function reviewsView(){return heading('GOOD WORK DESERVES A GOOD WORD.','Customer feedback','Feedback from completed projects. Feature reviews only with customer permission.','','')+`<div class="card-grid">${(db.reviews||[]).map(r=>`<article class="panel review-card"><div class="review-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p>${esc(r.text)}</p><strong>${esc(r.name)}</strong><small>${esc(r.company)} · ${date(r.created)}</small><div class="card-bottom"><span>${r.publishConsent?'Permission to publish':'Private feedback'}</span>${r.publishConsent&&r.rating>=4?`<button class="text-button" data-feature-review="${r.id}" data-featured="${!r.featured}">${r.featured?'Remove from quotes':'Feature on quotes'} ↗</button>`:''}</div></article>`).join('')||'<div class="empty">Mark an accepted quote as completed to let the customer leave feedback on its portal.</div>'}</div>`}
async function renderLeadForm(){try{const branding=await api('lead-form');$('#app').innerHTML=`<div class="customer-page lead-public"><header class="customer-header"><span class="document-brand">${branding.logoId?`<img class="company-logo" src="/branding/logo" alt="${esc(branding.company)}">`:esc(branding.company)}</span></header><section class="customer-actions"><div class="eyebrow">LET’S START SOMETHING GOOD.</div><h1>Tell us about your project.</h1><p>We’ll review your enquiry and get back to you with the next steps.</p><form id="lead-form"><div class="form-grid"><label>Your name<input name="name" required maxlength="200"></label><label>Email address<input name="email" type="email" required maxlength="300"></label><label>Company<input name="company" maxlength="200"></label><label>Phone<input name="phone" maxlength="100"></label></div><label>Project summary<input name="summary" required maxlength="300" placeholder="What would you like help with?"></label><label>Project details<textarea name="details" rows="5" maxlength="5000" placeholder="A little background, your timeline, and what success looks like…"></textarea></label><button class="button primary">Send enquiry →</button></form></section><footer>${esc(branding.company)}</footer></div>`;$('#lead-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('lead-form','POST',Object.fromEntries(new FormData(e.target)));$('.customer-actions').innerHTML='<h1>Thanks for getting in touch.</h1><p>Your enquiry has been received. The team will review it and get back to you.</p>'}catch(err){toast(err.message);button.disabled=false}}}catch(e){$('#app').innerHTML=`<div class="error-page"><h1>Enquiry form unavailable</h1><p>${esc(e.message)}</p></div>`}}
function render(){cleanupMacSettings();if(!['dashboard','quotes','contacts','templates','items','settings','leads','reviews'].includes(view))view='dashboard';if((['templates','items'].includes(view)&&db.currentUser?.permissions?.templatesItems===false)||(view==='settings'&&db.currentUser?.role==='member'))view='dashboard';document.body.classList.add('mac-app');document.body.classList.toggle('mac-settings',view==='settings');document.body.dataset.view=view;document.title='Dowi Quotes · '+view;$('#app').innerHTML=shell();$('#content').innerHTML=view==='dashboard'?dashboard():view==='quotes'?quotesView():view==='settings'?settingsView():view==='leads'?leadsView():view==='reviews'?reviewsView():collectionView(view);bind();bindCompanyControls();bindMacWorkspace(render);if(view==='settings'){bindIntegrations({api,$,esc,toast,modal,refresh});bindMacSettings({db,api,uploadFile,refresh,toast,render})}}
function modal(content,cls=''){const el=$('#modal');el.className=cls;el.innerHTML=`<button class="modal-close" aria-label="Close dialog">×</button>${content}`;if(!el.open)el.showModal();$('.modal-close').onclick=()=>el.close();el.onclick=e=>{if(e.target===el)el.close()}}
function ownerOptions(q){return `<option value="" ${!q.assigneeId?'selected':''}>Unassigned</option>${(db.teamMembers||[]).filter(m=>m.active||m.id===q.assigneeId).map(m=>`<option value="${esc(m.id)}" ${m.id===q.assigneeId?'selected':''}>${esc(m.email)}${m.active?'':' (Past team member)'}</option>`).join('')}`}
function newQuote(q=null,template=null,customer=null){editing=q?structuredClone(q):{title:'',assigneeId:db.currentUser?.id||'',contactId:customer||db.contacts[0]?.id||'',tax:db.settings.tax,notes:'Thank you for the opportunity to work together. Here’s what we have in mind.',terms:db.settings.terms,currency:db.settings.currency,exchangeRate:1,exchangeRateDate:'',exchangeRateSource:'same currency',expires:localDateInput(new Date(Date.now()+30*86400000)),attachments:[],items:template?structuredClone(template.items):[{name:'',description:'',qty:1,price:0,cost:0,optional:false,selected:true,discountType:'none',discountValue:0,editableQuantity:false}]};editing.items.forEach(i=>{i.discountType??='none';i.discountValue??=0;i.editableQuantity??=false});modal(`<div class="editor-heading"><div class="eyebrow">LET’S MAKE IT OFFICIAL.</div><h2>${q?'Edit quote':'A new opportunity.'}</h2><p>Great proposals start with the right details.</p></div><form id="quote-form"><div class="form-grid"><label>Quote title<input name="title" required value="${esc(editing.title)}" placeholder="e.g. Brand identity & website"></label><label>Customer<select name="contactId" required>${db.contacts.map(c=>`<option value="${c.id}" ${c.id===editing.contactId?'selected':''}>${esc(c.name)} · ${esc(c.company)}</option>`).join('')}</select></label><label>Responsible colleague<select name="assigneeId">${ownerOptions(editing)}</select></label><label>Valid until<input name="expires" type="date" value="${editing.expires.includes('T')?localDateInput(new Date(editing.expires)):editing.expires}" required></label><label>Tax (%)<input name="tax" type="number" min="0" max="100" step="0.01" value="${editing.tax}"></label><label>Quote currency<select id="quote-currency" name="currency">${[...new Set(["HKD","USD","CNY","JPY","SGD","GBP","EUR","AUD","CAD","NZD","CHF",editing.currency||db.settings.currency])].map(c=>`<option ${c===(editing.currency||db.settings.currency)?'selected':''}>${c}</option>`).join('')}</select></label><label>Exchange rate · 1 ${esc(editing.currency||db.settings.currency)} in ${esc(db.settings.currency)}<input id="exchange-rate" name="exchangeRate" type="number" min="0.00000001" step="any" value="${editing.exchangeRate||1}" required><small id="exchange-note" class="subtle">${esc(editing.exchangeRateSource||'same currency')}${editing.exchangeRateDate?` · ${esc(editing.exchangeRateDate)}`:''}</small></label><div class="exchange-action"><button type="button" class="button secondary compact" id="latest-rate">Use latest available rate</button></div><input type="hidden" name="exchangeRateDate" value="${esc(editing.exchangeRateDate||'')}"><input type="hidden" name="exchangeRateSource" value="${esc(editing.exchangeRateSource||'same currency')}"></div><label>Introduction<textarea name="notes" rows="2">${esc(editing.notes)}</textarea></label><div class="section-label"><h3>Quote items</h3><select id="add-library" aria-label="Add item from library"><option value="">Add from library…</option>${db.items.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></div><div id="editor-items"></div><button type="button" class="text-button add-item" id="add-item">＋ Add another item</button><section class="editor-attachments"><div class="section-label"><h3>Images & files</h3><label class="upload-button">＋ Attach file<input id="quote-file" type="file"></label></div><p class="subtle">Up to 10 files, 5 MB each. Images appear on the quote; documents are downloadable.</p><div id="draft-attachments"></div></section><div class="editor-total"><div>Quote total<strong id="editor-total"></strong></div><div class="editor-breakdown" id="editor-breakdown"></div></div><label>Terms & conditions<textarea name="terms" rows="2">${esc(editing.terms)}</textarea></label><div class="form-footer"><span>Save a draft. Publish when you’re ready.</span><button class="button primary">Save ${q?'changes':'draft'} →</button></div></form>`,'wide');renderItems();renderDraftAttachments();$('#quote-file').onchange=async e=>{try{if((editing.attachments||[]).length>=10)throw Error('A quote supports up to 10 attachments');e.target.disabled=true;const asset=await uploadFile(e.target.files[0]);editing.attachments??=[];editing.attachments.push(asset);renderDraftAttachments();toast('File attached')}catch(err){toast(err.message)}finally{e.target.disabled=false;e.target.value=''}};$('#add-item').onclick=()=>{syncItems();editing.items.push({name:'',description:'',qty:1,price:0,cost:0,optional:false,selected:true,discountType:'none',discountValue:0,editableQuantity:false});renderItems()};$('#add-library').onchange=e=>{if(!e.target.value)return;syncItems();editing.items.push({...db.items.find(i=>i.id===e.target.value),qty:1,optional:false,selected:true,discountType:'none',discountValue:0,editableQuantity:false});renderItems();e.target.value=''};const loadRate=async()=>{const from=$('#quote-currency').value,to=db.settings.currency;try{let rate;if(from===to)rate={from,to,rate:1,date:new Date().toISOString().slice(0,10),source:'same currency'};else rate=await api(`exchange-rate?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`);editing.currency=from;editing.exchangeRate=rate.rate;editing.exchangeRateDate=rate.date;editing.exchangeRateSource=rate.source;$('#exchange-rate').value=rate.rate;$('#quote-form [name=exchangeRateDate]').value=rate.date;$('#quote-form [name=exchangeRateSource]').value=rate.source;$('#exchange-note').textContent=`${rate.source} · ${rate.date}`;$('#quote-form label:has(#exchange-rate)').firstChild.textContent=`Exchange rate · 1 ${from} in ${to}`;renderPricingSummary()}catch(error){toast(error.message)}};$('#quote-currency').onchange=()=>{editing.currency=$('#quote-currency').value;loadRate()};$('#latest-rate').onclick=loadRate;$('#exchange-rate').oninput=e=>{editing.exchangeRate=Number(e.target.value);editing.exchangeRateSource='Manual entry';editing.exchangeRateDate=new Date().toISOString().slice(0,10);$('#quote-form [name=exchangeRateDate]').value=editing.exchangeRateDate;$('#quote-form [name=exchangeRateSource]').value=editing.exchangeRateSource;$('#exchange-note').textContent=`Manual entry · ${editing.exchangeRateDate}`};$('#quote-form').oninput=()=>renderPricingSummary();$('#quote-form').onchange=()=>renderPricingSummary();$('#quote-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.form-footer button');if(button.disabled)return;button.disabled=true;syncItems();const fields=Object.fromEntries(new FormData(e.target));try{await api(q?`quotes/${q.id}`:'quotes',q?'PUT':'POST',{...editing,...fields,tax:Number(fields.tax),exchangeRate:Number(fields.exchangeRate),expires:new Date(fields.expires+'T23:59:59').toISOString()});await refresh();$('#modal').close();toast(q?'Quote updated':'Draft saved. A good start!')}catch(e){toast(e.message);button.disabled=false}}}
function renderDraftAttachments(){if(!$('#draft-attachments'))return;$('#draft-attachments').innerHTML=(editing.attachments||[]).map(a=>`<div class="draft-attachment"><span>${esc(a.name)} <small>${Math.ceil(a.size/1024)} KB</small></span><button type="button" class="text-button" data-remove-file="${a.id}">Remove</button></div>`).join('');document.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>{editing.attachments=editing.attachments.filter(a=>a.id!==b.dataset.removeFile);renderDraftAttachments()})}
function editorSum(){syncItems();return total({...editing,tax:Number($('#quote-form [name=tax]').value)})}
function syncItems(){if(!$('#editor-items'))return;editing.items=[...document.querySelectorAll('.edit-item')].map((el,n)=>({...editing.items[n],name:el.querySelector('[data-field=name]').value,description:el.querySelector('[data-field=description]').value,qty:Number(el.querySelector('[data-field=qty]').value),price:Number(el.querySelector('[data-field=price]').value),cost:Number(el.querySelector('[data-field=cost]').value),discountType:el.querySelector('[data-field=discountType]').value,discountValue:Number(el.querySelector('[data-field=discountValue]').value||0),editableQuantity:el.querySelector('[data-field=editableQuantity]').checked,repeatUnit:el.querySelector('[data-field=repeatUnit]').value||null,repeatEvery:el.querySelector('[data-field=repeatEvery]').value?Number(el.querySelector('[data-field=repeatEvery]').value):null,repeatCount:el.querySelector('[data-field=repeatCount]').value?Number(el.querySelector('[data-field=repeatCount]').value):null,optional:el.querySelector('[data-field=optional]').checked,choiceGroup:el.querySelector('[data-field=choiceGroup]').value.trim(),selected:true}));const groups=new Set();editing.items.forEach(i=>{if(i.choiceGroup){i.selected=!groups.has(i.choiceGroup);groups.add(i.choiceGroup)}})}
function renderPricingSummary(){if(!$('#editor-items'))return;syncItems();editing.tax=Number($('#quote-form [name=tax]').value||0);const amounts=quoteAmounts(editing);$('#editor-total').textContent=money(amounts.total,editing.currency||db.settings.currency);$('#editor-breakdown').innerHTML=`<span>Subtotal after discounts: ${money(amounts.subtotal,editing.currency||db.settings.currency)}</span><span>Discount: ${money(amounts.discount,editing.currency||db.settings.currency)}</span><span>Total cost: ${money(amounts.cost,db.settings.currency)}</span><span>Gross profit: ${money(amounts.profit,db.settings.currency)} (${amounts.marginPercent.toFixed(1)}%)</span><span>Tax: ${money(amounts.tax,editing.currency||db.settings.currency)}</span><span>Total in ${db.settings.currency}: ${money(amounts.total*Number(editing.exchangeRate||1),db.settings.currency)}${editing.exchangeRateDate?` · rate ${editing.exchangeRateDate}`:''}</span>`;document.querySelectorAll('.edit-item').forEach((el,n)=>{const i=editing.items[n],a=itemAmounts(i),discountField=el.querySelector('[data-field=discountValue]');if(discountField)discountField.max=i.discountType==='percent'?'100':String(i.price);el.querySelector('.internal-line-summary').innerHTML=`Discount ${money(a.discount,editing.currency||db.settings.currency)} · Revenue ${money(a.revenue,editing.currency||db.settings.currency)} · Cost ${money(a.cost,db.settings.currency)} · Gross profit ${money(a.revenue*Number(editing.exchangeRate||1)-a.cost,db.settings.currency)}${i.repeatUnit?` · ${a.periods} × ${i.repeatEvery||1} ${i.repeatUnit}(s)`:''}`})}
function renderItems(){$('#editor-items').innerHTML=editing.items.map((i,n)=>`<div class="edit-item"><div class="item-inputs"><input data-field="name" value="${esc(i.name)}" required placeholder="Item name" aria-label="Item ${n+1} name"><input data-field="description" value="${esc(i.description)}" placeholder="A little detail…" aria-label="Item description"></div><label>QTY<input data-field="qty" type="number" min="0.01" step="0.01" value="${i.qty??1}" required></label><label>UNIT PRICE<input data-field="price" type="number" min="0" step="0.01" value="${i.price}" required></label><label>INTERNAL UNIT COST<input data-field="cost" type="number" min="0" step="0.01" value="${i.cost||0}" required></label><label>ITEM DISCOUNT<select data-field="discountType"><option value="none" ${(i.discountType||'none')==='none'?'selected':''}>None</option><option value="percent" ${i.discountType==='percent'?'selected':''}>Percent</option><option value="amount" ${i.discountType==='amount'?'selected':''}>Amount per unit</option></select></label><label>DISCOUNT VALUE<input data-field="discountValue" type="number" min="0" max="${i.discountType==='percent'?100:i.price}" step="0.01" value="${i.discountValue||0}"></label><label class="choice-group-label">ALTERNATIVE GROUP<input data-field="choiceGroup" value="${esc(i.choiceGroup||'')}" placeholder="Optional · e.g. Support tier" maxlength="100"></label><label class="choice-group-label">REPEAT UNIT<select data-field="repeatUnit"><option value="" ${!i.repeatUnit?'selected':''}>One-time</option><option value="month" ${i.repeatUnit==='month'?'selected':''}>Monthly</option><option value="year" ${i.repeatUnit==='year'?'selected':''}>Yearly</option></select></label><label>EVERY<input data-field="repeatEvery" type="number" min="1" max="12" step="1" value="${i.repeatEvery||1}" ${!i.repeatUnit?'disabled':''}></label><label>PERIODS<input data-field="repeatCount" type="number" min="1" max="1200" step="1" value="${i.repeatCount||1}" ${!i.repeatUnit?'disabled':''}></label><div class="item-options"><label><input type="checkbox" data-field="optional" ${i.optional?'checked':''}> Optional</label><label><input type="checkbox" data-field="editableQuantity" ${i.editableQuantity?'checked':''}> Customer can edit quantity</label><button type="button" data-remove="${n}" aria-label="Remove item">×</button></div><div class="internal-line-summary"></div></div>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{syncItems();editing.items.splice(Number(b.dataset.remove),1);renderItems()});renderPricingSummary()}
function quoteLogoURL(customer=false){return customer?'/api/'+(new URLSearchParams(location.search).has('preview')?'preview/':'shared/')+encodeURIComponent(location.pathname.split('/')[2])+'/logo':'/'+db.tenantId+'/branding/logo'}
function quoteDocument(q,c,settings,customer=false){const canEdit=customer&&!new URLSearchParams(location.search).has('preview')&&['Sent','Viewed'].includes(q.status)&&Date.parse(q.expires)>Date.now();const amounts=quoteAmounts(q),qmoney=n=>money(n,q.currency||settings.currency);return `<div class="quote-document"><div class="document-top"><span class="document-brand">${settings.logoId?`<img class="company-logo" src="${quoteLogoURL(customer)}" alt="${esc(settings.company)}">`:`<span class="workspace-icon">${esc(initials(settings.company))}</span>${esc(settings.company)}`}</span>${badge(q.status)}</div><div class="quote-facts"><div><span>FROM</span><strong>${esc(settings.company)}</strong><p>${esc(settings.email)}${settings.phone?'<br>'+esc(settings.phone):''}</p><p class="preserve-lines">${esc(settings.address||'')}</p></div><div><span>FOR</span><strong>${esc(c?.company||c?.name||'Customer')}</strong><span>TO</span><p>${esc(c?.name||'')}<br>${esc(c?.email||'')}</p><p class="preserve-lines">${esc(c?.address||'')}</p></div><div><span>QUOTE NUMBER</span><p>#${q.number}</p><span>DATE</span><p>${fullDate(q.created)}</p><span>EXPIRY DATE</span><p>${fullDate(q.expires)}</p></div></div><h1>${esc(q.title)}</h1><p class="document-notes">${esc(q.notes)}</p><div class="document-items">${q.items.map((i,n)=>{const a=itemAmounts(i);const choice=canEdit&&i.choiceGroup?`<label class="optional-label"><input class="alternative-choice" data-index="${n}" name="choice-${esc(i.choiceGroup)}" type="radio" ${i.selected?'checked':''}> ${esc(i.choiceGroup)} · choose one</label>`:customer&&i.choiceGroup?`<small class="optional-label">${esc(i.choiceGroup)} · ${i.selected?'Selected':'Not selected'}</small>`:canEdit&&i.optional?`<label class="optional-label"><input class="optional-choice" data-index="${n}" type="checkbox" ${i.selected?'checked':''}> Optional</label>`:i.optional?'<small class="optional-label">Optional</small>':'';const discountLabel=i.discountType==='percent'?`${Number(i.discountValue||0)}% off (${qmoney(i.price-a.unitPrice)} per unit)`:i.discountType==='amount'?`${qmoney(i.price-a.unitPrice)} off per unit`:'';return `<div class="document-item ${((i.optional||i.choiceGroup)&&!i.selected)?'not-selected':''}" data-document-item="${n}"><div>${choice}<h3>${esc(i.name)}</h3><p>${esc(i.description)}</p>${i.discountType&&i.discountType!=='none'?`<small class="discount-detail">List price ${qmoney(i.price)} · ${esc(discountLabel)} · ${qmoney(a.unitPrice)} net per unit</small>`:''}${i.repeatUnit?`<small class="repeat-detail">Repeats every ${i.repeatEvery||1} ${esc(i.repeatUnit)} for ${a.periods} period(s)</small>`:''}${customer?'':`<small class="internal-pricing">Internal cost ${money(a.cost,settings.currency)} · Gross profit ${money(a.revenue*Number(q.exchangeRate||1)-a.cost,settings.currency)}</small>`}</div><div class="price-block"><small>${qmoney(a.unitPrice)}${canEdit&&i.editableQuantity?`<br>Quantity <input class="customer-quantity" data-index="${n}" type="number" min="0.001" step="0.01" value="${i.qty}" aria-label="Quantity for ${esc(i.name)}">`:`<br>× ${i.qty}`} ${i.repeatUnit?`<br>× ${a.periods} periods`:''}</small><strong id="doc-line-${n}">${included(i)?qmoney(a.revenue):'Not included'}</strong></div></div>`}).join('')}</div><div class="document-totals"><p>Subtotal <span id="doc-subtotal">${qmoney(amounts.subtotal)}</span></p><p>Discount <span id="doc-discount">${qmoney(amounts.discount)}</span></p><p>Tax (${q.tax}%) <span id="doc-tax">${qmoney(amounts.tax)}</span></p><h2>Total ${q.currency||settings.currency} <span id="doc-total">${qmoney(amounts.total)}</span></h2></div>${(customer?shared.reviews:(db.reviews||[]).filter(r=>r.featured&&r.publishConsent).slice(0,3))?.length?`<section class="featured-reviews"><h3>A few words from our customers</h3><div class="review-grid">${(customer?shared.reviews:db.reviews.filter(r=>r.featured&&r.publishConsent).slice(0,3)).map(r=>`<article><span class="review-stars">${'★'.repeat(r.rating)}</span><p>${esc(r.text)}</p><strong>${esc(r.name)}</strong><small>${esc(r.company)}</small></article>`).join('')}</div></section>`:''}${q.attachments?.length?`<section class="quote-attachments"><h3>Images & files</h3><div class="attachment-grid">${attachmentLinks(q,customer)}</div></section>`:''}<div class="terms"><h3>Conditions of offer</h3><p>${esc(q.terms)}</p></div>${q.acceptedBy?`<div class="accepted-notice">✓ Accepted by ${esc(q.acceptedBy)}${q.acceptance?.reference?` · Order/reference ${esc(q.acceptance.reference)}`:''}</div>`:''}</div>`}
function openQuote(id){const q=db.quotes.find(q=>q.id===id);const financials=quoteAmounts(q);const subtotal=financials.subtotal;const cost=financials.cost;modal(`<div class="quote-actions">${["Sent","Viewed"].includes(q.status)?'<button class="button secondary compact" id="accept-on-behalf">Accept on behalf</button>':''}${db.mailEnabled&&["Draft","Sent","Viewed"].includes(q.status)?'<button class="button primary compact" id="email-quote">Send by email</button>':''}<button class="button secondary compact" id="print-quote">↓ Print / PDF</button><button class="button secondary compact" id="preview-quote">Preview as customer ↗</button>${q.status==='Draft'?'<button class="button secondary compact" id="edit-quote">Edit quote</button><button class="button primary compact" id="publish-quote">Publish quote ↗</button>':q.status!=='Accepted'?'<button class="button secondary compact" id="offline-quote">Take offline to edit</button>':''}${!['Draft','Withdrawn'].includes(q.status)?'<button class="button primary compact" id="copy-link">Copy customer link ↗</button>':''}</div><label>Responsible colleague<select id="quote-assignee">${ownerOptions(q)}</select></label>${quoteDocument(q,contact(q),db.settings)}<div class="detail-extra"><div class="internal-summary"><h3>Internal pricing · team only</h3><p>Discount: <strong>${quoteMoney(financials.discount,q)}</strong> · Cost: <strong>${quoteMoney(cost,q)}</strong> · Gross profit: <strong>${quoteMoney(financials.profit,q)} (${financials.marginPercent.toFixed(1)}%)</strong></p><p>Rate: 1 ${esc(q.currency||db.settings.currency)} = ${Number(q.exchangeRate||1)} ${esc(db.settings.currency)}${q.exchangeRateDate?` · ${esc(q.exchangeRateDate)}`:''}</p><p>${q.views||0} customer views ${q.lastViewed?'· Last viewed '+date(q.lastViewed):''}</p></div><div class="quote-actions"><button class="button secondary compact" id="duplicate-quote">Copy to new quote</button>${['Sent','Viewed'].includes(q.status)?'<button class="button secondary compact" id="withdraw-quote">Withdraw quote</button>':''}${q.status==='Accepted'&&q.progress!=='Complete'?'<button class="button secondary compact" id="complete-quote">Mark completed</button>':''}${q.progress==='Complete'?'<span class="badge accepted">Completed & archived</span>':''}</div><h3>Quote timeline</h3>${q.activity.map(a=>`<p>${esc(a.text)} <small>${date(a.date)}</small></p>`).join('')}<h3>Private notes · team only</h3>${(q.privateNotes||[]).map(n=>`<div class="message"><p>${esc(n.text)}</p><small>${date(n.date)}</small></div>`).join('')}<form id="private-note-form"><label>Add a private note<textarea name="text" required maxlength="3000" rows="2"></textarea></label><button class="button secondary compact">Save private note</button></form><h3>Customer questions & answers</h3>${q.messages.length?q.messages.map(m=>`<div class="message"><strong>${esc(m.author)}${m.staff?' · Team':''}</strong><p>${esc(m.text)}</p><small>${date(m.date)}</small></div>`).join(''):'<p>No questions yet.</p>'}<form id="staff-reply-form"><label>Reply to the customer<textarea name="text" required maxlength="3000" rows="2"></textarea></label><button class="button secondary compact">Post reply</button></form><h3>Follow-ups</h3>${(q.followups||[]).map(f=>`<p>${f.done?'✓':'◷'} ${date(f.due)} · ${esc(f.text||'Follow up with the customer')} ${!f.done?`<button class="text-button" data-followup-done="${f.id}">Mark done</button>`:''}</p>`).join('')}${['Sent','Viewed'].includes(q.status)?`<form id="followup-form"><div class="form-grid"><label>Follow-up date<input name="due" type="date" required value="${localDateInput(new Date(Date.now()+3*86400000))}"></label><label>Internal reminder<input name="text" maxlength="3000" placeholder="e.g. Check project timeline"></label></div><button class="button secondary compact">Schedule follow-up</button><p class="subtle">Internal reminder only; email delivery is not configured.</p></form>`:''}<button class="text-button" id="save-template">Save as template ↗</button></div>`,'wide document-modal');bindQuoteXero(q,{api,$,esc,toast});$('#print-quote').onclick=()=>window.print();$('#preview-quote').onclick=()=>{location.href='/q/'+q.token+'?preview=1'};const act=async(path,body,feedback)=>{try{await api(`quotes/${id}/${path}`,'POST',body);await refresh();openQuote(id);toast(feedback)}catch(e){toast(e.message)}};$('#quote-assignee').onchange=e=>act('assign',{assigneeId:e.target.value},'Responsible colleague updated');if($('#accept-on-behalf'))$('#accept-on-behalf').onclick=()=>staffAcceptance(q);if($('#email-quote'))$('#email-quote').onclick=()=>{if(confirm('Send this quote to '+contact(q).email+'? Drafts will be published.'))act('send-email',{requestId:crypto.randomUUID()},'Email queued. Refresh the quote to see delivery status.')};if($('#edit-quote'))$('#edit-quote').onclick=()=>newQuote(q);if($('#publish-quote'))$('#publish-quote').onclick=()=>act('status',{status:'Sent'},'Published. Copy the customer link to share.');if($('#offline-quote'))$('#offline-quote').onclick=()=>act('status',{status:'Draft'},'Taken offline. You can now edit the quote.');if($('#withdraw-quote'))$('#withdraw-quote').onclick=()=>act('status',{status:'Withdrawn'},'Quote withdrawn. Its customer link is unavailable.');if($('#complete-quote'))$('#complete-quote').onclick=()=>act('complete',{},'Quote completed and archived');$('#duplicate-quote').onclick=async()=>{try{const copy=await api(`quotes/${id}/duplicate`,'POST',{});await refresh();openQuote(copy.id);toast('Copied to a new draft')}catch(e){toast(e.message)}};if($('#copy-link'))$('#copy-link').onclick=async()=>{const base=db.publicPortalURL||location.origin;const link=base+'/q/'+q.token;try{await navigator.clipboard.writeText(link);toast('Customer link copied')}catch{modal(`<h2>Customer link</h2><input value="${esc(link)}" readonly aria-label="Customer link">`,'wide')}};$('#save-template').onclick=async()=>{try{await api('templates','POST',{name:q.title,description:q.notes,items:q.items});await refresh();toast('Added to your templates')}catch(e){toast(e.message)}};for(const [selector,path,feedback] of [['#private-note-form','notes','Private note saved'],['#staff-reply-form','messages','Reply posted'],['#followup-form','followups','Follow-up scheduled']])if($(selector))$(selector).onsubmit=e=>{e.preventDefault();act(path,Object.fromEntries(new FormData(e.target)),feedback)};document.querySelectorAll('[data-followup-done]').forEach(b=>b.onclick=()=>act('followup-done',{id:b.dataset.followupDone},'Follow-up completed'))}
function simpleForm(type,existing=null){const isItem=type==='items';modal(`<div class="eyebrow">BUILD YOUR WORKSPACE.</div><h2>${existing?'Update your '+(isItem?'item.':'contact.'):isItem?'A reusable item.':'A new connection.'}</h2><form id="simple-form"><label>${isItem?'Item name':'Full name'}<input name="name" required maxlength="200" value="${esc(existing?.name||'')}" placeholder="${isItem?'e.g. Website design':'e.g. Olivia Chen'}"></label>${isItem?`<label>Description<textarea name="description" rows="3">${esc(existing?.description||'')}</textarea></label><div class="form-grid"><label>Unit price<input name="price" type="number" min="0" step="0.01" required value="${existing?.price||0}"></label><label>Internal unit cost<input name="cost" type="number" min="0" step="0.01" required value="${existing?.cost||0}"></label></div>`:`<label>Company<input name="company" maxlength="200" value="${esc(existing?.company||'')}"></label><label>Email address<input name="email" type="email" maxlength="300" value="${esc(existing?.email||'')}"></label><label>Phone<input name="phone" maxlength="100" value="${esc(existing?.phone||'')}"></label><label>Address<textarea name="address" rows="2" maxlength="1000">${esc(existing?.address||'')}</textarea></label>`}<div class="form-footer"><button class="button primary">Save ${isItem?'item':'contact'} →</button></div></form>`);$('#simple-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');if(button.disabled)return;button.disabled=true;const b=Object.fromEntries(new FormData(e.target));if(isItem){b.price=Number(b.price);b.cost=Number(b.cost)}else b.color=existing?.color||'#e0eae6';try{await api(existing?`${type}/${existing.id}`:type,existing?'PUT':'POST',b);await refresh();$('#modal').close();toast('Saved to your workspace')}catch(e){toast(e.message);button.disabled=false}}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(){document.querySelectorAll('[data-edit-contact]').forEach(b=>b.onclick=()=>simpleForm('contacts',db.contacts.find(c=>c.id===b.dataset.editContact)));document.querySelectorAll('[data-edit-item]').forEach(b=>b.onclick=()=>simpleForm('items',db.items.find(i=>i.id===b.dataset.editItem)));document.querySelectorAll('[data-convert-lead]').forEach(b=>b.onclick=async()=>{try{const q=await api(`leads/${b.dataset.convertLead}/convert`,'POST',{});await refresh();openQuote(q.id);toast('Draft created from this enquiry')}catch(e){toast(e.message)}});document.querySelectorAll('[data-lead-status]').forEach(el=>el.onchange=async()=>{try{await api(`leads/${el.dataset.leadStatus}/status`,'POST',{status:el.value});await refresh();toast('Lead status updated')}catch(e){toast(e.message)}});document.querySelectorAll('[data-feature-review]').forEach(b=>b.onclick=async()=>{try{await api(`reviews/${b.dataset.featureReview}/feature`,'POST',{featured:b.dataset.featured==='true'});await refresh();toast('Review display updated')}catch(e){toast(e.message)}});if($('#global-search-form'))$('#global-search-form').onsubmit=e=>{e.preventDefault();query=new FormData(e.target).get('search');view='quotes';filter='All quotes';render()};document.querySelectorAll('[data-dashboard-mode]').forEach(b=>b.onclick=()=>{dashboardMode=b.dataset.dashboardMode;render()});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{view='quotes';filter=b.dataset.group==='Awaiting a response'||b.dataset.group==='Sent'?'Open':b.dataset.group;render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;query='';render()});document.querySelectorAll('[data-open]').forEach(b=>{b.onclick=()=>openQuote(b.dataset.open);b.onkeydown=e=>{if(e.key==='Enter')openQuote(b.dataset.open)}});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>newQuote(null,db.templates.find(t=>t.id===b.dataset.template)));document.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>newQuote(null,null,b.dataset.customer));document.querySelectorAll('[data-library]').forEach(b=>b.onclick=()=>newQuote(null,{items:[{...db.items.find(i=>i.id===b.dataset.library),qty:1,optional:false,selected:true}]}));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case'copy-lead-link':{const link=(db.publicPortalURL||location.origin)+'/lead';navigator.clipboard.writeText(link).then(()=>toast('Enquiry link copied')).catch(()=>modal(`<h2>Enquiry form link</h2><input value="${esc(link)}" readonly>`));break;}case'new-quote':newQuote();break;case'new-contact':simpleForm('contacts');break;case'new-item':simpleForm('items');break;case'new-template':modal(`<h2>Make your best quote a template.</h2><p>Select an existing quote, then choose “Save as template.”</p><div class="template-chooser">${db.quotes.map(q=>`<button class="button secondary" data-choose="${q.id}">${esc(q.title)} ↗</button>`).join('')}</div>`);document.querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>openQuote(b.dataset.choose));break;case'settings':view='settings';render();break;case'unanswered':modal(`<h2>Unanswered customer questions</h2>${db.quotes.filter(q=>q.messages.length&&!q.messages.at(-1).staff).map(q=>`<button class="button secondary" data-answer="${q.id}">${esc(q.title)} ↗</button>`).join('')||'<p class="subtle">You’re all caught up.</p>'}`,'wide');document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>openQuote(b.dataset.answer));break;case'activity':modal(`<h2>A little progress, every day.</h2>${activityList(30)}`,'wide');document.querySelectorAll('#modal [data-open]').forEach(b=>b.onclick=()=>openQuote(b.dataset.open));break;case'followups':view='quotes';filter='Open';render();break;case'export':download('dowi-quotes-workspace.json',JSON.stringify(db,null,2),'application/json');toast('Workspace exported');break;case'export-quotes':{const rows=[['Number','Title','Customer','Status','Value','Currency'],...db.quotes.map(q=>[q.number,q.title,contact(q).name,q.status,total(q).toFixed(2),q.currency||db.settings.currency])];download('quotes.csv',rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv');break;}}});if($('#search'))$('#search').oninput=e=>{query=e.target.value;const start=e.target.selectionStart;$('#content').innerHTML=quotesView();bind();$('#search').focus();$('#search').setSelectionRange(start,start)};if($('#quote-status-filter'))$('#quote-status-filter').onchange=e=>{filter=e.target.value;render()};if($('#quote-colleague-filter'))$('#quote-colleague-filter').onchange=e=>{colleague=e.target.value;render()};if($('#sort'))$('#sort').onchange=e=>{sort=e.target.value;render()};if($('#company-logo-file'))$('#company-logo-file').onchange=async e=>{try{e.target.disabled=true;const asset=await uploadFile(e.target.files[0]);if(!asset.type.startsWith('image/'))throw Error('Choose a PNG, JPEG or WebP image');$('#settings-form [name=logoId]').value=asset.id;toast('Logo uploaded. Save settings to apply it.')}catch(err){toast(err.message)}finally{e.target.disabled=false;e.target.value=''}};if($('#remove-logo'))$('#remove-logo').onclick=()=>{$('#settings-form [name=logoId]').value='';toast('Save settings to remove the logo')};if($('#webhooks-settings'))$('#webhooks-settings').onclick=()=>webhooksDialog().catch(e=>toast(e.message));if($('#domain-form'))$('#domain-form').onsubmit=async e=>{e.preventDefault();try{await api('domain','POST',Object.fromEntries(new FormData(e.target)));await refresh();toast('Domain added. Complete the CNAME and TXT records shown above.')}catch(error){toast(error.message)}};if($('#refresh-domain'))$('#refresh-domain').onclick=async()=>{try{await api('domain/refresh','POST',{});await refresh();toast('Domain status refreshed')}catch(error){toast(error.message)}};if($('#remove-domain'))$('#remove-domain').onclick=async()=>{try{await api('domain','DELETE',{});await refresh();toast('Custom domain removed')}catch(error){toast(error.message)}};if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();try{await api('settings','PUT',Object.fromEntries(new FormData(e.target)));await refresh();toast('Workspace settings saved')}catch(e){toast(e.message)}};if($('#load-ai-proposals'))$('#load-ai-proposals').onclick=()=>aiProposalsDialog().catch(error=>toast(error.message))}
function refreshSharedTotals(q){const a=quoteAmounts(q);q.items.forEach((i,n)=>{const line=$(`#doc-line-${n}`),row=document.querySelector(`[data-document-item=\"${n}\"]`);if(line)line.textContent=included(i)?quoteMoney(itemAmounts(i).revenue,q):'Not included';if(row)row.classList.toggle('not-selected',!included(i))});if($('#doc-subtotal'))$('#doc-subtotal').textContent=quoteMoney(a.subtotal,q);if($('#doc-discount'))$('#doc-discount').textContent=quoteMoney(a.discount,q);if($('#doc-tax'))$('#doc-tax').textContent=quoteMoney(a.tax,q);if($('#doc-total'))$('#doc-total').textContent=quoteMoney(a.total,q)}
async function renderShared(){try{const token=location.pathname.split('/')[2];const isPreview=new URLSearchParams(location.search).has('preview');shared=await api((isPreview?'preview/':'shared/')+token);if(!isPreview)startQuoteTracking(token,shared.viewChallenge);const {quote:q,contact:c,settings:s}=shared;const available=!isPreview&&['Sent','Viewed'].includes(q.status)&&Date.parse(q.expires)>Date.now();$('#app').innerHTML=`<div class="customer-page"><header class="customer-header"><span class="document-brand"><span class="workspace-icon">${esc(initials(s.company))}</span>${esc(s.company)}</span><button class="button secondary compact" id="customer-print">↓ Download PDF</button></header>${quoteDocument(q,c,s,true)}<section class="customer-actions">${isPreview?'<h2>Customer preview</h2><p>This preview is read-only. It does not count as a customer view, accept a quote, or post a customer message.</p>':available?`<form id="accept-form"><h2>Ready to make great things happen?</h2><p>Review the quote and terms above, then enter your name to accept.</p><label>Your full name<input name="name" required maxlength="150" value="${esc(c?.name||'')}"></label><label>Additional comments<textarea name="comment" maxlength="3000" rows="2" placeholder="Optional"></textarea></label><label>Your order/reference number<input name="reference" maxlength="200" placeholder="Optional"></label><label class="consent"><input type="checkbox" name="agreed" required> I agree to the quote and its terms.</label><button class="button primary">Accept quote ✓</button></form><button class="text-button decline-link" id="decline-quote">Decline this quote…</button>`:`<h2>${q.status==='Accepted'?'Your quote is accepted.':q.status==='Declined'?'This quote has been declined.':'This quote is no longer available for acceptance.'}</h2>${q.acceptance?`<p>Accepted ${date(q.acceptance.when)} by ${esc(q.acceptance.name)}</p>${q.acceptance.recordedByTeam?'<p>Acceptance recorded by the team.</p>':''}${q.acceptance.reference?`<p>Order/reference: ${esc(q.acceptance.reference)}</p>`:''}${q.acceptance.comment?`<p>${esc(q.acceptance.comment)}</p>`:''}`:''}`}</section><section class="customer-actions"><h2>Questions & answers</h2>${q.messages.map(m=>`<div class="message"><strong>${esc(m.author)}${m.staff?' · Team':''}</strong><p>${esc(m.text)}</p><small>${date(m.date)}</small></div>`).join('')}<form id="question-form"><label>Your name<input name="name" required maxlength="150" value="${esc(c?.name||'')}"></label><label>Ask a question<textarea name="text" required maxlength="3000" rows="3"></textarea></label><button class="button secondary">Ask a question →</button></form></section>${!isPreview&&q.status==='Accepted'&&q.progress==='Complete'?`<section class="customer-actions"><h2>How did we do?</h2>${shared.review?'<p>Thank you for sharing your feedback.</p>':`<form id="customer-review-form"><label>Your name<input name="name" value="${esc(c?.name||'')}" required maxlength="200"></label><label>Your rating<select name="rating"><option value="5">★★★★★ · Excellent</option><option value="4">★★★★☆ · Good</option><option value="3">★★★☆☆ · Okay</option><option value="2">★★☆☆☆ · Needs improvement</option><option value="1">★☆☆☆☆ · Poor</option></select></label><label>Your feedback<textarea name="text" required maxlength="3000" rows="4"></textarea></label><label class="consent"><input name="publishConsent" type="checkbox"> You may display this review on your quotes.</label><button class="button primary">Share feedback →</button></form>`}</section>`:''}<footer>Prepared with Dowi Quotes · ${esc(s.company)}</footer></div>`;if($('#customer-review-form'))$('#customer-review-form').onsubmit=async e=>{e.preventDefault();const fields=new FormData(e.target);try{await api(`shared/${token}/reviews`,'POST',{name:fields.get('name'),text:fields.get('text'),rating:Number(fields.get('rating')),publishConsent:fields.get('publishConsent')==='on'});await renderShared();toast('Thank you for your feedback')}catch(e){toast(e.message)}};$('#customer-print').onclick=()=>window.print();document.querySelectorAll('.alternative-choice').forEach(el=>el.onchange=()=>{const n=Number(el.dataset.index),group=q.items[n].choiceGroup;q.items.forEach((i,j)=>{if(i.choiceGroup===group)i.selected=j===n});refreshSharedTotals(q)});document.querySelectorAll('.optional-choice').forEach(el=>el.onchange=()=>{q.items[Number(el.dataset.index)].selected=el.checked;refreshSharedTotals(q)});document.querySelectorAll('.customer-quantity').forEach(el=>el.oninput=()=>{q.items[Number(el.dataset.index)].qty=Number(el.value);refreshSharedTotals(q)});if($('#accept-form'))$('#accept-form').onsubmit=async e=>{e.preventDefault();try{const fields=Object.fromEntries(new FormData(e.target));await api(`shared/${token}/accept`,'POST',{...fields,agreed:fields.agreed==='on',selected:q.items.map((i,n)=>i.selected?n:-1).filter(n=>n>=0),quantities:Object.fromEntries(q.items.filter(i=>i.editableQuantity).map(i=>[i.id,i.qty]))});await renderShared();toast('Quote accepted. Thank you!')}catch(e){toast(e.message)}};if($('#decline-quote'))$('#decline-quote').onclick=()=>{modal(`<h2>Decline this quote</h2><p>Let the team know why this proposal isn’t the right fit.</p><form id="decline-form"><label>Your name<input name="name" value="${esc(c?.name||'')}" maxlength="150" required></label><label>Comments<textarea name="comment" maxlength="3000" rows="3"></textarea></label><button class="button secondary">Confirm decline</button></form>`);$('#decline-form').onsubmit=async e=>{e.preventDefault();try{await api(`shared/${token}/decline`,'POST',Object.fromEntries(new FormData(e.target)));$('#modal').close();await renderShared();toast('Quote declined. Your feedback was saved.')}catch(e){toast(e.message)}}};if(isPreview){$('#question-form').querySelectorAll('input,textarea,button').forEach(el=>el.disabled=true);if($('#customer-review-form'))$('#customer-review-form').querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=true)}$('#question-form').onsubmit=async e=>{e.preventDefault();try{await api(`shared/${token}/messages`,'POST',Object.fromEntries(new FormData(e.target)));await renderShared();toast('Your question was added')}catch(e){toast(e.message)}}}catch(e){$('#app').innerHTML=`<div class="error-page"><h1>Quote unavailable</h1><p>${esc(e.message)}</p></div>`}}
async function webhooksDialog(){const data=await api('webhooks');const w=data.config;modal(`<div class="eyebrow">CONNECT YOUR WORKFLOWS.</div><h2>Webhooks & delivery log</h2><p class="subtle">Send signed JSON to your internal tools when quote events occur.</p>${w.paused?'<p class="error-notice">Delivery paused after repeated failures. Save configuration or replay an event to resume.</p>':''}<form id="webhook-form"><label>Destination URL<input name="url" type="url" value="${esc(w.url)}" placeholder="https://your-system.example/webhooks/dowi-quotes"></label><label>Customer portal base URL<input name="baseURL" type="url" required value="${esc(w.baseURL)}"></label><label>Signing secret ${w.hasSecret?'(leave blank to keep current secret)':''}<input name="secret" type="password" autocomplete="new-password" placeholder="Enter your own secret to verify signatures"></label><label class="consent"><input name="enabled" type="checkbox" ${w.enabled?'checked':''}> Enable webhook delivery</label><div class="webhook-events">${data.events.map(event=>`<label class="consent"><input type="checkbox" name="events" value="${event}" ${w.events.includes(event)?'checked':''}> ${event}</label>`).join('')}</div><button class="button primary compact">Save configuration</button></form><div class="section-label"><h3>Test an event</h3><select id="test-event">${data.events.map(e=>`<option>${e}</option>`).join('')}</select><button class="button secondary compact" id="test-webhook" ${!w.url?'disabled':''}>Queue test</button></div><p class="subtle">Retries after 5, 10 and 15 minutes. Four failed delivery attempts pause delivery. Logs retained for 7 days. Signature: X-Dowi-Quotes-Signature (HMAC-SHA256).</p><h3>Recent deliveries</h3><div class="delivery-log">${data.deliveries.length?data.deliveries.map(d=>`<div class="delivery-row"><div><strong>${esc(d.event)}</strong><small>${date(d.created)} · ${d.attempts} attempts · ${esc(d.error||'')}</small></div><span>${esc(d.status)} ${d.responseCode||''}</span><button class="text-button" data-replay="${d.id}">Replay</button></div>`).join(''):'<p class="subtle">No deliveries yet.</p>'}</div><button class="text-button" id="refresh-deliveries">Refresh log ↻</button>`,'wide');$('#webhook-form').onsubmit=async e=>{e.preventDefault();const fields=new FormData(e.target);try{await api('webhooks','PUT',{url:fields.get('url'),baseURL:fields.get('baseURL'),secret:fields.get('secret'),enabled:fields.get('enabled')==='on',events:fields.getAll('events')});await refresh();await webhooksDialog();toast('Webhook settings saved')}catch(e){toast(e.message)}};$('#test-webhook').onclick=async()=>{try{await api('webhooks/test','POST',{event:$('#test-event').value});await webhooksDialog();toast('Test event queued')}catch(e){toast(e.message)}};$('#refresh-deliveries').onclick=()=>webhooksDialog().catch(e=>toast(e.message));document.querySelectorAll('[data-replay]').forEach(b=>b.onclick=async()=>{try{await api('webhooks/replay','POST',{id:b.dataset.replay});await webhooksDialog();toast('Event queued for replay')}catch(e){toast(e.message)}})}
if(location.pathname.startsWith('/q/'))renderShared();else if(location.pathname==='/lead')renderLeadForm();else refresh().catch(e=>{$('#app').innerHTML=`<div class="error-page"><a href="/login">Sign in</a><h1>Couldn’t open your workspace</h1><p>${esc(e.message)}</p><button id="retry-workspace">Try again</button></div>`;$('#retry-workspace').onclick=()=>location.reload()});

function staffAcceptance(q){
 modal(`<h2>Accept on behalf</h2><p>Record the customer’s agreement received outside the portal. The authorization record is visible only to your team.</p><form id="staff-accept-form"><label>Customer full name<input name="name" required maxlength="150" value="${esc(contact(q).name)}"></label><label>Authorization record<textarea name="evidence" required maxlength="3000" placeholder="e.g. Customer approval email received today"></textarea></label><label>Order/reference number<input name="reference" maxlength="200"></label><label>Customer comments<textarea name="comment" maxlength="3000"></textarea></label><h3>Customer’s selected items</h3>${q.items.map((i,n)=>`<label class="consent"><input type="${i.choiceGroup?'radio':'checkbox'}" name="${i.choiceGroup?'group-'+esc(i.choiceGroup):'selected'}" value="${n}" data-staff-selection ${i.selected!==false?'checked':''} ${!i.optional&&!i.choiceGroup?'disabled':''}>${esc(i.name)} · ${quoteMoney(itemAmounts(i).revenue,q)}${i.choiceGroup?' · '+esc(i.choiceGroup):''}</label>`).join('')}<label class="consent"><input type="checkbox" name="authorized" required>The customer agreed to the quote and terms and authorized me to record acceptance.</label><button class="button primary">Record acceptance</button></form>`,'wide');
 $('#staff-accept-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;const fields=Object.fromEntries(new FormData(form));try{await api(`quotes/${q.id}/accept-on-behalf`,'POST',{...fields,authorized:fields.authorized==='on',agreed:fields.authorized==='on',selected:Array.from(form.querySelectorAll('[data-staff-selection]:checked'),el=>Number(el.value))});await refresh();openQuote(q.id);toast('Customer acceptance recorded')}catch(err){toast(err.message);button.disabled=false}};
}

let trackingCleanup;
function startQuoteTracking(token,challenge){
 trackingCleanup?.();let stopped=false,confirmed=false,visibleSince=null,inflight=false,nextAt=0;
 const key='dowi-viewer';let visitor;
 try{visitor=localStorage.getItem(key);if(!visitor){visitor=crypto.randomUUID().replaceAll('-','');localStorage.setItem(key,visitor)}}catch{visitor=crypto.randomUUID().replaceAll('-','')}
 async function tick(){if(stopped||inflight||Date.now()<nextAt)return;if(document.visibilityState!=='visible'){visibleSince=null;return}visibleSince??=Date.now();if(Date.now()-visibleSince<3000)return;inflight=true;try{const result=await api(`shared/${token}/${confirmed?'heartbeat':'view'}`,'POST',{challenge,visitor});challenge=result.viewChallenge;confirmed=true;nextAt=Date.now()+30000}catch{}finally{inflight=false}}
 const visibility=()=>{visibleSince=document.visibilityState==='visible'?Date.now():null};document.addEventListener('visibilitychange',visibility);visibility();
 const interval=setInterval(tick,3000);trackingCleanup=()=>{stopped=true;clearInterval(interval);document.removeEventListener('visibilitychange',visibility)};
}

